import {CHICKEN,COOP_LEVELS} from './chicken-config.js';import {FEATURES} from './features.js';import {t} from './locales.js';
import {eggSaleValue} from './chicken-eggs.js';
import {chickenRecoveryReason} from './chicken-runtime.js';
/** @param {import('./engine.js').State} state @param {import('./market.js').Send} send @param {HTMLElement} host */
export function renderChickenLots(state,send,host){if(!FEATURES.chicken)return;for(const lot of state.chicken?.inventory||[]){const row=document.createElement('div');row.className='market-lot';row.dataset.eggLot=lot.id;const label=document.createElement('span');label.textContent=t('eggs')+' · '+t('grade')+' '+lot.grade+' ×'+lot.quantity;const b=document.createElement('button');b.type='button';b.className='action-button primary';b.dataset.sellEgg=lot.id;b.textContent=t('sell')+' · +'+eggSaleValue(lot)+' '+t('coins');b.addEventListener('click',()=>send('sellEggs',{eggLot:lot.id}));row.append(label,b);host.append(row);}}
/** @param {import('./engine.js').State} state @param {import('./market.js').Send} send @param {HTMLElement} host */
export function renderChickenShop(state,send,host){const c=state.chicken;if(!FEATURES.chicken||!c?.visited||!c.coop)return;const row=document.createElement('div');row.className='market-lot';const text=document.createElement('span');text.id='chicken-feed-store';text.textContent=t('feedStock')+': '+Math.round(c.feedStoreG)+' g';const b=document.createElement('button');b.id='buy-feed';b.type='button';b.className='action-button';const reason=c.feedStoreG+CHICKEN.feedBagG>CHICKEN.feedStoreMaxG?'feedStoreFull':state.coins<CHICKEN.feedBagPrice?'noCoins':'';b.disabled=!!reason;b.title=t(reason||'buyFeed');b.textContent=t('buyFeed')+' · '+CHICKEN.feedBagG+' g / '+CHICKEN.feedBagPrice+' '+t('coins');b.addEventListener('click',()=>send('buyFeed'));row.append(text,b);host.append(row);
 const upgrade=document.createElement('div');upgrade.className='market-lot';const label=document.createElement('span');label.id='coop-capacity';label.textContent=t('coopRoom')+': '+c.hens.length+'/'+COOP_LEVELS[c.coop.level].capacity;const button=document.createElement('button');button.id='upgrade-coop';button.type='button';button.className='action-button';const next=COOP_LEVELS[c.coop.level+1],blocked=!next?'coopMax':c.mission.step<7?'chickenSellFirst':state.coins<next.price?'noCoins':'';button.disabled=!!blocked;button.title=t(blocked||'upgradeCoop');button.textContent=!next?t('coopMax'):t('upgradeCoop')+' · '+next.price+' '+t('coins');button.addEventListener('click',()=>send('upgradeCoop'));upgrade.append(label,button);host.append(upgrade);
 const aid=document.createElement('button');aid.id='chicken-aid';aid.type='button';aid.className='action-button recovery';const aidReason=chickenRecoveryReason(state);aid.disabled=!!aidReason;aid.textContent=t('chickenAid');aid.title=t(aidReason||'chickenAidDescription');aid.addEventListener('click',()=>send('chickenRecovery'));const note=document.createElement('p');note.className='market-note';note.textContent=t(aidReason||'chickenAidDescription');host.append(aid,note);
 const hen=document.createElement('button');hen.id='buy-hen';hen.type='button';hen.className='action-button';const henReason=c.hens.length>=COOP_LEVELS[c.coop.level].capacity?'coopFull':c.mission.step<8?'chickenChapterFirst':state.coins<CHICKEN.henPrice?'noCoins':'';hen.disabled=!!henReason;hen.title=t(henReason||'buyHen');hen.textContent=t('buyHen')+' · '+CHICKEN.henPrice+' '+t('coins');hen.addEventListener('click',()=>send('buyHen'));host.append(hen);
}
